import React, { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import WorkerSplash from "./components/WorkerSplash";
import WorkerSignIn from "./components/SignIn";

function App() {
  const [view, setView] = useState("splash");

  return (
    // We keep the Lenin Blue as the "Under-layer" so no white flashes occur
    <div className="bg-[#003366] min-h-screen w-full overflow-hidden">
      <AnimatePresence mode="wait">
        {view === "splash" && (
          <motion.div
            key="splash"
            // EXIT EFFECT: The splash slides up and fades
            initial={{ opacity: 1 }}
            exit={{ y: -1000, opacity: 0 }} 
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
            className="h-screen w-full"
          >
            <WorkerSplash onComplete={() => setView("signin")} />
          </motion.div>
        )}

        {view === "signin" && (
          <motion.div
            key="signin"
            // ENTRANCE EFFECT: The sign-in screen slides up from the bottom
            initial={{ y: "100%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ duration: 0.9, ease: [0.16, 1, 0.3, 1] }}
            className="h-screen w-full bg-[#FFF24D]" // It brings the yellow with it
          >
            <WorkerSignIn onLogin={() => setView("dashboard")} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default App;
